          { id: 'C', textEN: "She worries about making a mistake.", textVN: "Cô ấy lo lắng về việc mắc lỗi." },
          { id: 'D', textEN: "She sometimes gets nervous on television.", textVN: "Cô ấy đôi khi hồi hộp khi lên sóng." }
